-- =====================================================================
--  September  —  the words, moved behind the paywall
--
--  WHAT THIS DOES
--  Creates `book_nights` if it is not there yet, and puts 28 nights of
--  Wonderful Is His Way into it. The table carries the same rule as
--  story_texts: Postgres hands a row to a subscriber, or to anyone for a
--  story marked free, and to nobody else.
--
--  HOW TO RUN IT
--    Supabase  ->  SQL Editor  ->  New query  ->  paste  ->  Ctrl+A  ->  Run
--
--  Safe to run more than once: it updates rather than duplicating.
--  Run the three book files in any order.
-- =====================================================================

create table if not exists public.book_nights (
  id         text primary key,   -- the catalog id, e.g. 'b6-w1-n1'
  book       int,
  night      text,               -- "Week 1 · Night 1"
  title      text,
  reference  text,
  beats      jsonb not null,     -- the whole night: pictures, words, moments
  is_free    boolean not null default false,
  updated_at timestamptz not null default now()
);

alter table public.book_nights enable row level security;

-- The same rule story_texts already uses. Editing the website's JavaScript
-- gets a reader precisely nothing, because the words never leave the database.
drop policy if exists "read book night" on public.book_nights;
create policy "read book night"
  on public.book_nights for select
  to authenticated
  using (is_free or public.lst_is_subscriber());

-- ---------------------------------------------------------------------
--  Wonderful Is His Way
-- ---------------------------------------------------------------------
insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n1', 9, 'Week 1 · Night 1', 'Bless the Lord, O My Soul', 'Psalm 103', '[{"type": "cover", "img": "images/book/sep-01-0.jpg", "alt": "Cover illustration for “Bless the Lord, O My Soul”"}, {"type": "story", "img": "images/book/sep-01-1.jpg", "alt": "Illustration: Long ago, a man named David wanted to thank Heavenly Father with his whole heart.", "text": ["Long ago, a man named David wanted to thank Heavenly Father with his whole heart. So he sang a happy song: “Bless Heavenly Father, O my soul! I will remember all the good things He does!”", "David remembered how kind Heavenly Father is. He forgives us when we’re sorry. He helps us feel better when we’re sad. He fills our lives with good things, like a warm hug that never ends.", "“Heavenly Father loves us like the very best daddy,” David sang. “As high as the sky is above the earth, that’s how big His love is for us!”"]}, {"type": "story", "img": "images/book/sep-01-2.jpg", "alt": "Illustration: And when we say we’re sorry, Heavenly Father takes our mistakes far, far away — as far as the sunrise is from…", "text": ["And when we say we’re sorry, Heavenly Father takes our mistakes far, far away — as far as the sunrise is from the sunset. He remembers them no more.", "Heavenly Father’s love is so big and so gentle. No matter what, He loves you with His whole heart, all the way to the sky and back."]}, {"type": "moment", "img": "images/book/sep-01-3.jpg", "alt": "Illustration: Willow fits tonight because she feels how gentle and forgiving love can be.", "text": ["Willow fits tonight because she feels how gentle and forgiving love can be. In Willow’s world today: Willow spilled her juice all over the floor and felt scared she was in trouble. But Mom just gave her a hug and said, “It’s okay — let’s clean it up together.” Willow’s worried heart melted into a happy one. Just like David sang about Heavenly Father’s kind, forgiving love, Willow felt how big and gentle that love can be."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-01-4.jpg", "alt": "Illustration: Let’s bless Heavenly Father like David!", "text": ["Let’s bless Heavenly Father like David! Wrap your arms around yourself in a big hug, then stretch them wa-a-ay up high to the sky. His love is bigger than we can even reach! Can you show me how high His love goes?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father loves you higher than the sky and takes your mistakes far away when you’re sorry! You are so loved, sweet one. What is one good thing Heavenly Father has done for you that you can thank Him for?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-01-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did David want to remember about Heavenly Father?”", "“How big is Heavenly Father’s love for us?”", "“What is one good thing Heavenly Father has done for you that you can thank Him for?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-01-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n2', 9, 'Week 1 · Night 2', 'He Hears My Voice', 'Psalm 116', '[{"type": "cover", "img": "images/book/sep-02-0.jpg", "alt": "Cover illustration for “He Hears My Voice”"}, {"type": "story", "img": "images/book/sep-02-1.jpg", "alt": "Illustration: There once was a person who felt sad and afraid.", "text": ["There once was a person who felt sad and afraid. Big troubles were all around, and he didn’t know what to do. So he did the best thing of all — he called out to Heavenly Father.", "“Please help me, Heavenly Father!” he prayed. And guess what? Heavenly Father heard every single word.", "Heavenly Father listened close and helped him. His sadness turned to gladness, and his heart felt calm again. “I love Heavenly Father,” he sang, “because He hears me when I call!”"]}, {"type": "story", "img": "images/book/sep-02-2.jpg", "alt": "Illustration: The person was so thankful.", "text": ["The person was so thankful. He decided he would keep praying and keep loving Heavenly Father for the rest of his life.", "Whenever you talk to Heavenly Father, He hears you too — every whisper, every prayer. You are never, ever alone."]}, {"type": "moment", "img": "images/book/sep-02-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father to hear him when things feel hard.", "text": ["Beau fits tonight because he trusts Heavenly Father to hear him when things feel hard. In Beau’s world today: Beau got lost from Dad for a scary minute at the busy store. His heart pounded, but he remembered to whisper, “Heavenly Father, help me,” and stay put. Soon Dad came around the corner! “Heavenly Father heard me,” Beau said. Just like the person who called out and was heard, Beau learned that Heavenly Father listens the moment we call."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-02-4.jpg", "alt": "Illustration: Let’s call out to Heavenly Father!", "text": ["Let’s call out to Heavenly Father! Cup your hands around your mouth and softly call, “I love You, Heavenly Father!” Now put your hand on your ear — He always hears. Can you show me your best listening ears?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Whenever you talk to Heavenly Father, He hears every word — even a tiny whisper! He loves to listen to you. What would you like to tell Heavenly Father tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-02-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person do when he felt sad and afraid?”", "“What did Heavenly Father do when he called?”", "“What would you like to tell Heavenly Father tonight?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-02-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n3', 9, 'Week 1 · Night 3', 'This Is the Day!', 'Psalm 118', '[{"type": "cover", "img": "images/book/sep-03-0.jpg", "alt": "Cover illustration for “This Is the Day!”"}, {"type": "story", "img": "images/book/sep-03-1.jpg", "alt": "Illustration: One morning, a happy song-writer woke up and looked at the brand-new day.", "text": ["One morning, a happy song-writer woke up and looked at the brand-new day. The sun was shining, the birds were singing, and his heart felt full of joy.", "“This is the day that Heavenly Father made!” he sang. “I will be happy and glad in it!”", "He knew that every single day is a gift from Heavenly Father. Some days are big and exciting; some days are quiet and small. But every day is made by Him."]}, {"type": "story", "img": "images/book/sep-03-2.jpg", "alt": "Illustration: “Thank You, Heavenly Father, for You are so good!” the person sang.", "text": ["“Thank You, Heavenly Father, for You are so good!” the person sang. “Your love lasts forever and ever!”", "When you wake up tomorrow, you can remember: this new day is a gift, made just for you by Heavenly Father who loves you."]}, {"type": "moment", "img": "images/book/sep-03-3.jpg", "alt": "Illustration: Scout fits tonight because Scout finds something wonderful in every new day.", "text": ["Scout fits tonight because Scout finds something wonderful in every new day. In Scout’s world today: it was a plain, rainy morning with no big plans. But Scout said, “I wonder what good things today will bring?” and went looking — and found a puddle to splash, a rainbow after lunch, and a cozy story with Grandma. Just like the song-writer who was glad for the day Heavenly Father made, Scout discovered that every day holds a gift when we look for it."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-03-4.jpg", "alt": "Illustration: Let’s welcome the new day!", "text": ["Let’s welcome the new day! Stretch your arms up in a big yawn, then open them wide like the morning sun coming up. “This is the day Heavenly Father made!” Can you show me your happiest good-morning stretch?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Every new day is a gift made just for you by Heavenly Father! You can wake up glad and look for the good in it. What is one thing you’re excited to do tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-03-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who made this brand-new day?”", "“What did the song-writer say he would be?”", "“What is one thing you’re excited to do tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-03-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n4', 9, 'Week 1 · Night 4', 'A Lamp for My Feet', 'Psalm 119', '[{"type": "cover", "img": "images/book/sep-04-0.jpg", "alt": "Cover illustration for “A Lamp for My Feet”"}, {"type": "story", "img": "images/book/sep-04-1.jpg", "alt": "Illustration: The longest song in all the Psalms is about something very special: Heavenly Father’s words, the scriptures.", "text": ["The longest song in all the Psalms is about something very special: Heavenly Father’s words, the scriptures. The song-writer loved them so much!", "“Your words are like a lamp for my feet,” he sang, “and a bright light for my path.” A lamp helps us see where to walk in the dark.", "When we don’t know what to do, Heavenly Father’s words show us the way — just like a little light helps us take the next safe step."]}, {"type": "story", "img": "images/book/sep-04-2.jpg", "alt": "Illustration: The song-writer even said, “I keep Your words safe inside my heart.” He learned them and remembered them, like…", "text": ["The song-writer even said, “I keep Your words safe inside my heart.” He learned them and remembered them, like hiding a treasure where it can never be lost.", "You can keep Heavenly Father’s words in your heart too. When you listen to scripture stories, you’re filling your heart with a light that helps you always know the way."]}, {"type": "moment", "img": "images/book/sep-04-3.jpg", "alt": "Illustration: Wren fits tonight because she treasures Heavenly Father’s words in her heart.", "text": ["Wren fits tonight because she treasures Heavenly Father’s words in her heart. In Wren’s world today: Wren couldn’t decide whether to tattle or be kind when her friend made a little mistake. Then she remembered a scripture story about being gentle, and it lit up the right thing to do — like a little lamp. She chose kindness. Just like the song-writer whose path was lit by Heavenly Father’s words, Wren found that the scriptures show us the way."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-04-4.jpg", "alt": "Illustration: Let’s light our little lamp!", "text": ["Let’s light our little lamp! Hold your hands like you’re carrying a lantern out in front of you, and take slow, careful steps. The light shows the way! Can you walk your safe little path with your lamp?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father’s words are like a little lamp that shows you the way — and you can keep them safe in your heart! What is one thing scripture stories have taught you to do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-04-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the song-writer say Heavenly Father’s words were like?”", "“Where did he keep Heavenly Father’s words safe?”", "“What is one thing scripture stories have taught you to do?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-04-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n5', 9, 'Week 1 · Night 5', 'You Know Me!', 'Psalm 139', '[{"type": "cover", "img": "images/book/sep-05-0.jpg", "alt": "Cover illustration for “You Know Me!”"}, {"type": "story", "img": "images/book/sep-05-1.jpg", "alt": "Illustration: One song-writer thought about something amazing: Heavenly Father knows everything about him!", "text": ["One song-writer thought about something amazing: Heavenly Father knows everything about him! He sang a wondering song about it.", "“Heavenly Father, You know when I sit down and when I stand up. You know my thoughts and every word before I say it. You are always with me!”", "He knew that wherever he went — up high or far away — Heavenly Father was right there, watching over him with love."]}, {"type": "story", "img": "images/book/sep-05-2.jpg", "alt": "Illustration: “You made me,” he sang, “and I am wonderfully made!” Every part of us — our fingers, our smiles, our giggles…", "text": ["“You made me,” he sang, “and I am wonderfully made!” Every part of us — our fingers, our smiles, our giggles — was carefully made by Heavenly Father.", "Isn’t that wonderful? Heavenly Father knows you all the way through, and He made you just right. You are precious and special to Him."]}, {"type": "moment", "img": "images/book/sep-05-3.jpg", "alt": "Illustration: Wren fits tonight because she loves to wonder at how amazing she’s made.", "text": ["Wren fits tonight because she loves to wonder at how amazing she’s made. In Wren’s world today: Wren looked at her own hand and wondered, “How did Heavenly Father make my fingers wiggle and my heart go thump?” She felt so special knowing He made every part of her on purpose. Just like the song-writer who marveled that he was wonderfully made, Wren discovered that Heavenly Father made her just right."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-05-4.jpg", "alt": "Illustration: Let’s show how well Heavenly Father knows us!", "text": ["Let’s show how well Heavenly Father knows us! Wiggle your fingers (He made those!), pat your head (He knows your thoughts!), and point to your smile (He made that too!). Can you show me all the wonderful parts He made?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father knows everything about you and made you wonderfully — there is no one else exactly like you! How does it feel to know Heavenly Father made you just right?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-05-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What does Heavenly Father know about us?”", "“How did Heavenly Father make each of us?”", "“How does it feel to know Heavenly Father made you just right?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-05-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n6', 9, 'Week 1 · Night 6', 'Children Are a Gift', 'Psalm 127', '[{"type": "cover", "img": "images/book/sep-06-0.jpg", "alt": "Cover illustration for “Children Are a Gift”"}, {"type": "story", "img": "images/book/sep-06-1.jpg", "alt": "Illustration: Heavenly Father loves families very much.", "text": ["Heavenly Father loves families very much. One of the Psalms is a happy song all about home and children.", "“Unless Heavenly Father helps build the house, the builders work for nothing,” the song says. That means Heavenly Father is the one who helps our family and home grow strong and happy.", "Then the song says something sweet: “Children are a gift from Heavenly Father!” Every child — including YOU — is a special present He gives to a family."]}, {"type": "story", "img": "images/book/sep-06-2.jpg", "alt": "Illustration: The song paints a happy picture: a mom and dad and their little ones gathered close, like young plants growing…", "text": ["The song paints a happy picture: a mom and dad and their little ones gathered close, like young plants growing round a table full of love.", "Your family is a gift, and you are a gift too! Heavenly Father helps your home be a place of love, where you are treasured every single day."]}, {"type": "moment", "img": "images/book/sep-06-3.jpg", "alt": "Illustration: Willow fits tonight because she cherishes the people in her home.", "text": ["Willow fits tonight because she cherishes the people in her home. In Willow’s world today: at dinner, Willow looked around at everyone laughing together and felt her heart go warm. “I’m so glad you’re my family,” she said, and gave her little brother a hug — even though he’d been silly all day. Just like the song about children being a gift from Heavenly Father, Willow felt how precious her family is."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-06-4.jpg", "alt": "Illustration: Let’s make a cozy family circle!", "text": ["Let’s make a cozy family circle! Reach your arms out wide like they’re wrapping all around your family, then pull them into a big squeeze-hug. Home is full of love! Can you give a great big family hug?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Your family is a gift from Heavenly Father — and so are you! He helps your home be full of love. Who in your family are you thankful for tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-06-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who helps build a happy home?”", "“What does the song say children are?”", "“Who in your family are you thankful for tonight?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-06-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n7', 9, 'Week 1 · Night 7', 'Let Everything Praise Him!', 'Psalms 148–150', '[{"type": "cover", "img": "images/book/sep-07-0.jpg", "alt": "Cover illustration for “Let Everything Praise Him!”"}, {"type": "story", "img": "images/book/sep-07-1.jpg", "alt": "Illustration: The very last songs in the Psalms are the happiest of all!", "text": ["The very last songs in the Psalms are the happiest of all! They shout, “Praise Heavenly Father!” over and over with joy.", "The song calls to everyone and everything: “Sun and moon, praise Him! Shining stars, praise Him! Mountains and trees, praise Him!”", "Even the animals join in! “Whales in the sea, birds in the sky, little bugs and big lions — praise Heavenly Father!” All of creation says thank You to the One who made them."]}, {"type": "story", "img": "images/book/sep-07-2.jpg", "alt": "Illustration: And then the very last line: “Let EVERYTHING that breathes praise Heavenly Father!” That means you too — with…", "text": ["And then the very last line: “Let EVERYTHING that breathes praise Heavenly Father!” That means you too — with singing, clapping, and a happy, thankful heart.", "The whole world is like one big, joyful song to Heavenly Father. And you get to be part of it! Isn’t that wonderful?"]}, {"type": "moment", "img": "images/book/sep-07-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to notice everything praising Heavenly Father.", "text": ["Scout fits tonight because Scout loves to notice everything praising Heavenly Father. In Scout’s world today: on a walk, Scout listened to the birds chirping, the wind whooshing the trees, and a puppy’s happy bark. “It’s like the whole world is singing to Heavenly Father!” Scout said, and started humming a thank-You song too. Just like the psalm that calls everything to praise Him, Scout discovered that all creation — and Scout — can join the joyful song."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-07-4.jpg", "alt": "Illustration: Let’s join the whole world’s song!", "text": ["Let’s join the whole world’s song! Clap your hands, stomp your feet, and cheer, “Praise Heavenly Father!” Now take a big breath — you have breath, so you can praise Him too! Can you make your most joyful praising sound?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Everything that breathes can praise Heavenly Father — and that means YOU! You can praise Him with singing, clapping, and a thankful heart. What is your favorite happy way to praise Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-07-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who does the song say should praise Heavenly Father?”", "“Since you can breathe, what can you do?”", "“What is your favorite happy way to praise Heavenly Father?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-07-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n1', 9, 'Week 2 · Night 1', 'Trust Him to Lead the Way', 'Proverbs 3', '[{"type": "cover", "img": "images/book/sep-08-0.jpg", "alt": "Cover illustration for “Trust Him to Lead the Way”"}, {"type": "story", "img": "images/book/sep-08-1.jpg", "alt": "Illustration: A wise man named Solomon wrote down lots of good advice to help us live happy lives.", "text": ["A wise man named Solomon wrote down lots of good advice to help us live happy lives. We call his sayings Proverbs. One of the very best is about trusting Heavenly Father.", "“Trust in Heavenly Father with ALL your heart,” Solomon wrote. “Don’t try to figure everything out by yourself.”", "Sometimes we don’t know which way to go or what to do. That’s okay! Solomon said, “Ask Heavenly Father, and He will show you the right path.”"]}, {"type": "story", "img": "images/book/sep-08-2.jpg", "alt": "Illustration: It’s like walking with someone who knows the way.", "text": ["It’s like walking with someone who knows the way. We don’t have to see the whole road — we just hold His hand and take the next step.", "When you trust Heavenly Father with your whole heart, He leads you on good paths, step by step. You can trust Him, even when you can’t see what’s ahead."]}, {"type": "moment", "img": "images/book/sep-08-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father even when he can’t see the whole way.", "text": ["Beau fits tonight because he trusts Heavenly Father even when he can’t see the whole way. In Beau’s world today: Beau’s family went on a hike, and the trail wound up a hill where Beau couldn’t see the top. His legs felt unsure. But Dad said, “Just take the next step — I know the way.” Beau trusted and kept going, and the view at the top was amazing! Just like Solomon said to trust Heavenly Father to direct our paths, Beau learned to trust the One who knows the way."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-08-4.jpg", "alt": "Illustration: Let’s follow the leader!", "text": ["Let’s follow the leader! Hold out your hand like you’re holding Heavenly Father’s, and take slow, trusting steps forward. He knows the way! Can you walk your path, trusting your guide?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you don’t know which way to go, you can trust Heavenly Father with your whole heart — He will lead you, step by step! What is something you can trust Heavenly Father to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-08-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How much should we trust Heavenly Father?”", "“What does Heavenly Father do when we trust Him?”", "“What is something you can trust Heavenly Father to help you with?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-08-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n2', 9, 'Week 2 · Night 2', 'Wisdom, a Hidden Treasure', 'Proverbs 2', '[{"type": "cover", "img": "images/book/sep-09-0.jpg", "alt": "Cover illustration for “Wisdom, a Hidden Treasure”"}, {"type": "story", "img": "images/book/sep-09-1.jpg", "alt": "Illustration: Wise Solomon wanted everyone to have something wonderful called wisdom.", "text": ["Wise Solomon wanted everyone to have something wonderful called wisdom. Wisdom means knowing the good and right thing to do.", "“Look for wisdom like you’re searching for hidden treasure!” Solomon said. “Dig for it, hunt for it — it’s more precious than gold and shiny jewels!”", "How do we find this treasure? Solomon said to listen to Heavenly Father, and to listen to the wise grown-ups who love us, like our mom and dad."]}, {"type": "story", "img": "images/book/sep-09-2.jpg", "alt": "Illustration: “Pay attention, my child,” he wrote.", "text": ["“Pay attention, my child,” he wrote. “Keep my good words close, and you will grow wise and happy.”", "Every time you listen and learn, you’re finding a little more treasure. Heavenly Father loves to help you grow wise, one good lesson at a time."]}, {"type": "moment", "img": "images/book/sep-09-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to search out good and wonderful things.", "text": ["Scout fits tonight because Scout loves to search out good and wonderful things. In Scout’s world today: Scout wanted to build the tallest sandcastle but didn’t know how. Instead of giving up, Scout asked Grandpa, who knew a clever trick — wet sand sticks better! Scout listened, tried it, and built a mighty castle. Just like Solomon said to hunt for wisdom like treasure, Scout discovered that listening to wise helpers is like finding gold."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-09-4.jpg", "alt": "Illustration: Let’s hunt for treasure!", "text": ["Let’s hunt for treasure! Put your hand above your eyes and “search” all around, then dig-dig-dig with your hands and — “I found it!” — hold up the sparkly treasure of wisdom. Can you show me your excited treasure-hunting face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Wisdom is a treasure worth hunting for — and you find it by listening to Heavenly Father and the wise people who love you! What is something wise you learned from a grown-up you love?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-09-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Solomon say to look for like treasure?”", "“How do we find the treasure of wisdom?”", "“What is something wise you learned from a grown-up you love?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-03-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n3', 9, 'Week 2 · Night 3', 'A Soft, Kind Answer', 'Proverbs 15', '[{"type": "cover", "img": "images/book/sep-10-0.jpg", "alt": "Cover illustration for “A Soft, Kind Answer”"}, {"type": "story", "img": "images/book/sep-10-1.jpg", "alt": "Illustration: Wise Solomon knew that the words we say are very powerful.", "text": ["Wise Solomon knew that the words we say are very powerful. They can make a heart happy or a heart hurt.", "“A soft, kind answer makes angry feelings go away,” Solomon taught. “But mean, grumpy words just make things worse.”", "Imagine two friends. One shouts, “You broke it!” — and everyone gets upset. But if that friend says softly, “It’s okay, let’s fix it together,” the mad feelings melt like ice in the sun."]}, {"type": "story", "img": "images/book/sep-10-2.jpg", "alt": "Illustration: Soft words are gentle words.", "text": ["Soft words are gentle words. Kind words are healing words. They help everyone feel calm and loved.", "Heavenly Father can help you choose soft, kind words — even when you feel a little grumpy. Gentle words make the whole world happier."]}, {"type": "moment", "img": "images/book/sep-10-3.jpg", "alt": "Illustration: Willow fits tonight because gentle words are her superpower.", "text": ["Willow fits tonight because gentle words are her superpower. In Willow’s world today: Willow’s brother knocked over her block tower and she felt her face go hot and mad. She almost yelled — but instead she took a breath and said softly, “That’s okay, will you help me build it again?” Her brother smiled and helped, and the mad feeling floated away. Just like Solomon taught that a soft answer turns anger away, Willow found that gentle words make peace."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-10-4.jpg", "alt": "Illustration: Let’s practice soft words!", "text": ["Let’s practice soft words! First, make a loud grumpy face and shake your fists — grr! Now take a slow breath, soften your face, and whisper, “It’s okay.” Can you feel how a soft answer calms us down?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you feel grumpy, you can choose soft, kind words — and watch the angry feelings melt away! Gentle words make hearts happy. When could you use a soft answer this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-10-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What does a soft, kind answer do to angry feelings?”", "“What do mean, grumpy words do?”", "“When could you use a soft answer this week?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-10-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n4', 9, 'Week 2 · Night 4', 'Loving, Helping Hands', 'Proverbs 31', '[{"type": "cover", "img": "images/book/sep-11-0.jpg", "alt": "Cover illustration for “Loving, Helping Hands”"}, {"type": "story", "img": "images/book/sep-11-1.jpg", "alt": "Illustration: Near the end of Proverbs is a beautiful song about a wonderful woman — a mom who loved her family with all her…", "text": ["Near the end of Proverbs is a beautiful song about a wonderful woman — a mom who loved her family with all her heart.", "She worked hard with happy hands. She made yummy food, cared for her home, and helped people who needed her.", "She was kind and wise. When she spoke, gentle and good words came out, and she wasn’t afraid of hard work or new days."]}, {"type": "story", "img": "images/book/sep-11-2.jpg", "alt": "Illustration: The best part?", "text": ["The best part? Her children loved her so much. “Her little ones stand up and call her blessed,” the song says. That means they were so thankful for her!", "Heavenly Father gives us loving people — moms, dads, grandmas, grandpas — who work hard to care for us. We can thank them, and love them, and help with our own two hands too."]}, {"type": "moment", "img": "images/book/sep-11-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to care for others like the kind woman in the song.", "text": ["Willow fits tonight because she loves to care for others like the kind woman in the song. In Willow’s world today: Willow noticed Mom was tired after a long day. So Willow used her helping hands — she put her toys away without being asked and brought Mom a pretend cup of tea. Mom’s face lit up. “Thank you, my helper!” Just like the loving woman whose family called her blessed, Willow learned that caring hands make a home warm."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-11-4.jpg", "alt": "Illustration: Let’s use loving, helping hands!", "text": ["Let’s use loving, helping hands! Pretend to stir a pot, fold a blanket, and give a pat on the back. Now clap for the people who care for you! Can you show me how YOU could help with your hands tomorrow?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father gives you loving people who work hard to care for you — and you can thank them AND help with your own hands! Who could you thank and help tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-11-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How did the woman use her hands?”", "“What did her children call her?”", "“Who could you thank and help tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-11-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n5', 9, 'Week 2 · Night 5', 'A Time for Everything', 'Ecclesiastes 3', '[{"type": "cover", "img": "images/book/sep-12-0.jpg", "alt": "Cover illustration for “A Time for Everything”"}, {"type": "story", "img": "images/book/sep-12-1.jpg", "alt": "Illustration: A wise teacher once wrote a thoughtful book called Ecclesiastes.", "text": ["A wise teacher once wrote a thoughtful book called Ecclesiastes. In it, he shared a gentle truth: there is a right time for everything.", "“There’s a time to plant seeds and a time to pick the fruit,” he said. “A time to laugh and a time to cry. A time to hug and a time to rest.”", "Heavenly Father made the world with seasons and times. Winter comes, then spring. Morning comes, then night. Everything has its own special time."]}, {"type": "story", "img": "images/book/sep-12-2.jpg", "alt": "Illustration: Some days are for playing and giggling.", "text": ["Some days are for playing and giggling. Some days are for resting and being quiet. Some feelings come and go, and that’s okay — each one has its time.", "Heavenly Father is with us in every season and every time. We can trust Him whether we’re laughing or crying, busy or still. He holds all our times in His loving hands."]}, {"type": "moment", "img": "images/book/sep-12-3.jpg", "alt": "Illustration: Wren fits tonight because she thinks about the right time for things.", "text": ["Wren fits tonight because she thinks about the right time for things. In Wren’s world today: Wren wanted to play outside, but it was pouring rain. Instead of fussing, she wondered, “Maybe this is a time to stay cozy inside.” So she read books and built a fort, and when the sun came out later, it was the perfect time to splash in puddles. Just like the wise teacher said there’s a time for everything, Wren learned to trust each season’s time."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-12-4.jpg", "alt": "Illustration: Let’s move through the times!", "text": ["Let’s move through the times! Pretend to plant a tiny seed, then reach up like it’s growing tall. Now give a big laugh — “ha ha!” — then a slow, calm breath. Can you show me a time to jump and a time to be still?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["There’s a right time for everything — a time to play and a time to rest — and Heavenly Father is with you in every one! What is something this is the right time for tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-12-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What are some of the times the teacher talked about?”", "“Who is with us in every season and time?”", "“What is something this is the right time for tonight?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-12-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n6', 9, 'Week 2 · Night 6', 'Remember Him While You’re Little', 'Ecclesiastes 12', '[{"type": "cover", "img": "images/book/sep-13-0.jpg", "alt": "Cover illustration for “Remember Him While You’re Little”"}, {"type": "story", "img": "images/book/sep-13-1.jpg", "alt": "Illustration: The wise teacher of Ecclesiastes had one very special piece of advice, just for young people like you.", "text": ["The wise teacher of Ecclesiastes had one very special piece of advice, just for young people like you.", "“Remember Heavenly Father now, while you are young!” he said. Don’t wait until you’re big and grown up — start loving Him today.", "When we’re little, our hearts are soft and ready to learn, like fresh soil ready for seeds. It’s the perfect time to plant love for Heavenly Father deep inside."]}, {"type": "story", "img": "images/book/sep-13-2.jpg", "alt": "Illustration: Every prayer you say, every story you hear, every kind thing you do helps you know Heavenly Father better — ri…", "text": ["Every prayer you say, every story you hear, every kind thing you do helps you know Heavenly Father better — right now, while you’re small.", "You don’t have to wait to be a friend of Heavenly Father. You can start today, and grow closer to Him every single day of your happy life."]}, {"type": "moment", "img": "images/book/sep-13-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to start the adventure of knowing Heavenly Father early.", "text": ["Scout fits tonight because Scout loves to start the adventure of knowing Heavenly Father early. In Scout’s world today: Scout’s big cousin said, “You’re too little to say prayers by yourself.” But Scout said, “No I’m not — I can start now!” and folded little arms and prayed a sweet, simple prayer all alone. Just like the wise teacher said to remember Heavenly Father while young, Scout discovered you’re never too little to know Him."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-13-4.jpg", "alt": "Illustration: Let’s start now!", "text": ["Let’s start now! Point to yourself and say, “I can love Heavenly Father today!” Now plant a pretend seed in your heart and watch it grow tall. Can you show me your heart growing love for Him, starting right now?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You don’t have to wait until you’re grown up to know Heavenly Father — you can start today, while you’re little! What is one way you can grow closer to Heavenly Father right now?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-13-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“When did the wise teacher say to remember Heavenly Father?”", "“Are you ever too little to love Heavenly Father?”", "“What is one way you can grow closer to Heavenly Father right now?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-13-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n7', 9, 'Week 2 · Night 7', 'A Good Name', 'Proverbs 22', '[{"type": "cover", "img": "images/book/sep-14-0.jpg", "alt": "Cover illustration for “A Good Name”"}, {"type": "story", "img": "images/book/sep-14-1.jpg", "alt": "Illustration: Wise Solomon shared one more treasure: he said a good name is better than piles of gold and silver.", "text": ["Wise Solomon shared one more treasure: he said a good name is better than piles of gold and silver.", "What is a “good name”? It means being someone people can trust — someone honest, kind, and true. When you do good, your name becomes a good name.", "Solomon knew that money and toys come and go. But being a good, honest person is a treasure that lasts forever."]}, {"type": "story", "img": "images/book/sep-14-2.jpg", "alt": "Illustration: Every time you tell the truth, keep a promise, or do the right thing, you’re building your good name — like ad…", "text": ["Every time you tell the truth, keep a promise, or do the right thing, you’re building your good name — like adding a shiny brick to a strong, tall wall.", "Heavenly Father is so happy when we choose to be honest and good. A good name is one of the best treasures of all, and you can build yours every day."]}, {"type": "moment", "img": "images/book/sep-14-3.jpg", "alt": "Illustration: Beau fits tonight because he chooses to be honest, even when it’s hard.", "text": ["Beau fits tonight because he chooses to be honest, even when it’s hard. In Beau’s world today: Beau accidentally broke a little toy while playing. No one saw. He could have stayed quiet — but his tummy felt yucky. So he took a brave breath and told the truth: “I broke it, and I’m sorry.” His mom hugged him and said, “Thank you for being honest.” Just like Solomon said a good name is a treasure, Beau built his good name by telling the truth."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-14-4.jpg", "alt": "Illustration: Let’s build a good name!", "text": ["Let’s build a good name! Stand up tall and proud, put your hand on your heart, and say, “I will be honest and good!” Now stack pretend bricks, one on top of another. Can you build your strong, good name nice and tall?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["A good name — being honest, kind, and true — is a treasure worth more than gold, and you build it every time you do right! When could it be brave to tell the truth this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-14-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Solomon say is better than gold and silver?”", "“How do we build a good name?”", "“When could it be brave to tell the truth this week?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-14-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n1', 9, 'Week 3 · Night 1', 'White as Snow', 'Isaiah 1', '[{"type": "cover", "img": "images/book/sep-15-0.jpg", "alt": "Cover illustration for “White as Snow”"}, {"type": "story", "img": "images/book/sep-15-1.jpg", "alt": "Illustration: Long ago, Heavenly Father sent a prophet named Isaiah to share His messages.", "text": ["Long ago, Heavenly Father sent a prophet named Isaiah to share His messages. One of Isaiah’s most beautiful messages was full of love and hope.", "Sometimes people made wrong choices, and their hearts felt dark and heavy, like a shirt with big red stains.", "But Heavenly Father said something wonderful through Isaiah: “Come, let’s talk it over. Even if your mistakes are as red as scarlet, I can make you as white and clean as fresh snow!”"]}, {"type": "story", "img": "images/book/sep-15-2.jpg", "alt": "Illustration: Isn’t that amazing?", "text": ["Isn’t that amazing? When we’re truly sorry and come to Heavenly Father, He washes our hearts pure and clean — whiter than the whitest snow.", "No mistake is too big for Heavenly Father’s love. He always welcomes us back and makes us clean and new. That is His happy promise to you."]}, {"type": "moment", "img": "images/book/sep-15-3.jpg", "alt": "Illustration: Willow fits tonight because she knows the gift of being made clean and new.", "text": ["Willow fits tonight because she knows the gift of being made clean and new. In Willow’s world today: Willow said an unkind word to her friend and felt a heavy, yucky feeling inside. She went back, gave a hug, and said, “I’m sorry — that wasn’t kind.” Right away her heart felt light and clean, like fresh snow. Just like Heavenly Father’s promise to make our hearts white as snow, Willow found that saying sorry brings a clean, happy heart."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-15-4.jpg", "alt": "Illustration: Let’s think of clean, white snow!", "text": ["Let’s think of clean, white snow! Wiggle your fingers down slowly like gentle snowflakes falling, then brush your hands over your heart — all clean! Can you show me your fresh, snowy-clean heart?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["No mistake is too big — when you’re sorry, Heavenly Father washes your heart white as snow, clean and new! What helps you feel better after you’ve made a mistake?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-15-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Heavenly Father promise to make our hearts like?”", "“Is any mistake too big for Heavenly Father’s love?”", "“What helps you feel better after you’ve made a mistake?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-15-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n2', 9, 'Week 3 · Night 2', 'Here Am I, Send Me', 'Isaiah 6', '[{"type": "cover", "img": "images/book/sep-16-0.jpg", "alt": "Cover illustration for “Here Am I, Send Me”"}, {"type": "story", "img": "images/book/sep-16-1.jpg", "alt": "Illustration: One day, the prophet Isaiah had an amazing experience.", "text": ["One day, the prophet Isaiah had an amazing experience. In a beautiful vision, he saw Heavenly Father’s shining throne, high and glorious, filling the temple with light.", "Bright angels flew all around, singing, “Holy, holy, holy!” Everything felt so wonderful and full of Heavenly Father’s love.", "Isaiah felt very small, but an angel gently touched his lips with something warm and bright from the altar. Right away, Isaiah felt clean and ready, and his worries floated away."]}, {"type": "story", "img": "images/book/sep-16-2.jpg", "alt": "Illustration: Then Isaiah heard Heavenly Father ask, “Who will go and share My message with My people?” Isaiah didn’t wait e…", "text": ["Then Isaiah heard Heavenly Father ask, “Who will go and share My message with My people?” Isaiah didn’t wait even a moment.", "“Here am I! Send me!” Isaiah said bravely. He was ready and willing to help Heavenly Father. When Heavenly Father needs a helper, we can be brave and say, “Send me!” too."]}, {"type": "moment", "img": "images/book/sep-16-3.jpg", "alt": "Illustration: Beau the Brave", "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-16-4.jpg", "alt": "Illustration: Let’s be a willing helper like Isaiah!", "text": ["Let’s be a willing helper like Isaiah! Raise your hand up high like you’re volunteering, and say big and brave, “Here am I — send me!” Can you show me how ready you are to help?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When there’s good work to do, you can be brave and willing like Isaiah and say, “Here am I — send me!” What is a good way you could be a helper tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-16-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the angels sing in Isaiah’s vision?”", "“What did Isaiah say when Heavenly Father needed a helper?”", "“What is a good way you could be a helper tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-16-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n3', 9, 'Week 3 · Night 3', 'Come to Heavenly Father’s House', 'Isaiah 2', '[{"type": "cover", "img": "images/book/sep-17-0.jpg", "alt": "Cover illustration for “Come to Heavenly Father’s House”"}, {"type": "story", "img": "images/book/sep-17-1.jpg", "alt": "Illustration: Isaiah shared a happy message about a special place: Heavenly Father’s holy house, the temple.", "text": ["Isaiah shared a happy message about a special place: Heavenly Father’s holy house, the temple.", "“In the last days,” Isaiah said, “Heavenly Father’s house will stand up high on a mountain, and people from everywhere will want to go there!”", "“Come,” the people will say to each other. “Let’s go up to Heavenly Father’s house! He will teach us His good ways, and we will walk in His paths.”"]}, {"type": "story", "img": "images/book/sep-17-2.jpg", "alt": "Illustration: The temple is a peaceful, holy place where we feel very close to Heavenly Father.", "text": ["The temple is a peaceful, holy place where we feel very close to Heavenly Father. It’s like His special home, full of light and quiet love.", "We can love going to Heavenly Father’s house too. Whether it’s the temple or church, it’s a wonderful place to feel Him near and learn His gentle ways."]}, {"type": "moment", "img": "images/book/sep-17-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves the journey to special places.", "text": ["Scout fits tonight because Scout loves the journey to special places. In Scout’s world today: Scout’s family drove to see the temple, all lit up and beautiful. Scout pressed against the window and gasped, “It’s like a castle of light!” On the peaceful grounds, Scout felt happy and calm and close to Heavenly Father. Just like Isaiah’s message about going up to Heavenly Father’s house, Scout discovered how special it feels to be near His holy home."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-17-4.jpg", "alt": "Illustration: Let’s go up to Heavenly Father’s house!", "text": ["Let’s go up to Heavenly Father’s house! March your feet up a pretend hill — up, up, up — then fold your arms reverently and whisper, “It’s so peaceful here.” Can you show me your quiet, reverent face inside His house?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father’s house is a special, peaceful place where you can feel Him close — and you can be eager to go! How do you feel when you’re in a place that feels close to Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-17-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Where did the people want to go up to?”", "“What did they say Heavenly Father would teach them?”", "“How do you feel when you’re in a place that feels close to Heavenly Father?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-17-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n4', 9, 'Week 3 · Night 4', 'A Special Baby Is Coming', 'Isaiah 9', '[{"type": "cover", "img": "images/book/sep-18-0.jpg", "alt": "Cover illustration for “A Special Baby Is Coming”"}, {"type": "story", "img": "images/book/sep-18-1.jpg", "alt": "Illustration: Isaiah shared the happiest secret of all — a promise about a very special baby who would come someday.", "text": ["Isaiah shared the happiest secret of all — a promise about a very special baby who would come someday.", "“Unto us a child will be born!” Isaiah said. “And He will be wonderful. He will be called the Prince of Peace!”", "This special baby was Jesus, Heavenly Father’s own Son. Isaiah told about Him long, long before He was born, because Heavenly Father wanted His people to have hope."]}, {"type": "story", "img": "images/book/sep-18-2.jpg", "alt": "Illustration: Jesus would be a mighty helper, full of love and peace.", "text": ["Jesus would be a mighty helper, full of love and peace. He would show everyone the way back to Heavenly Father.", "Even a long time ago, Heavenly Father was planning something wonderful for His children. He always keeps His promises — and the promise of Jesus was the most wonderful of all."]}, {"type": "moment", "img": "images/book/sep-18-3.jpg", "alt": "Illustration: Wren fits tonight because she loves to wonder about Heavenly Father’s beautiful plans.", "text": ["Wren fits tonight because she loves to wonder about Heavenly Father’s beautiful plans. In Wren’s world today: Wren saw her aunt getting ready for a new baby and wondered, “Isn’t it amazing how Heavenly Father plans good things before they even happen?” She thought about how He promised baby Jesus long ago too. Just like Isaiah wondered at the promise of the Prince of Peace, Wren marveled at Heavenly Father’s wonderful, hope-filled plans."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-18-4.jpg", "alt": "Illustration: Let’s think about the happy promise!", "text": ["Let’s think about the happy promise! Rock your arms gently like you’re holding a sweet baby, and whisper softly, “The Prince of Peace is coming.” Can you show me how gently we hold something precious?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Long ago, Heavenly Father promised a special baby — Jesus, the Prince of Peace — because He loves you and wanted you to have hope! What good thing are you feeling hopeful about?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-18-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say the special baby would be called?”", "“Who was the special baby that was promised?”", "“What good thing are you feeling hopeful about?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-18-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n5', 9, 'Week 3 · Night 5', 'The Peaceful Kingdom', 'Isaiah 11', '[{"type": "cover", "img": "images/book/sep-19-0.jpg", "alt": "Cover illustration for “The Peaceful Kingdom”"}, {"type": "story", "img": "images/book/sep-19-1.jpg", "alt": "Illustration: Isaiah shared a dream of a beautiful, peaceful world that Heavenly Father is preparing — a world where nothing…", "text": ["Isaiah shared a dream of a beautiful, peaceful world that Heavenly Father is preparing — a world where nothing is scary and everyone is safe.", "In this happy place, the wolf and the little lamb lie down together as friends. The lion and the calf rest side by side. No one is afraid anymore!", "And guess who leads them all? A little child! “A little child shall lead them,” Isaiah said. Even the smallest one is safe and gentle there."]}, {"type": "story", "img": "images/book/sep-19-2.jpg", "alt": "Illustration: In Heavenly Father’s peaceful world, no one gets hurt and no one is mean.", "text": ["In Heavenly Father’s peaceful world, no one gets hurt and no one is mean. Everything is filled with kindness, safety, and love.", "Heavenly Father wants us to feel that peace even now. When we’re kind and gentle, we bring a little bit of His peaceful world right into our homes today."]}, {"type": "moment", "img": "images/book/sep-19-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to make peace and help everyone feel safe.", "text": ["Willow fits tonight because she loves to make peace and help everyone feel safe. In Willow’s world today: at the park, a big kid and a little kid were both grabbing the same swing and starting to fuss. Willow gently said, “You can both have a turn — I’ll help count!” Soon they were laughing together. Just like Isaiah’s peaceful world where the lamb and lion are friends, Willow helped make a little pocket of peace."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-19-4.jpg", "alt": "Illustration: Let’s make a peaceful world!", "text": ["Let’s make a peaceful world! Pretend to pet a soft, gentle lamb, then a big friendly lion, right next to each other. Now give a calm, happy sigh — “aahh.” Can you show me your most peaceful, gentle face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is preparing a peaceful world where everyone is safe — and you can bring a little of that peace today by being kind and gentle! How could you help someone feel peaceful and safe tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-19-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who lies down together as friends in Isaiah’s peaceful world?”", "“Who leads them all?”", "“How could you help someone feel peaceful and safe tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-19-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n6', 9, 'Week 3 · Night 6', 'I Will Trust and Not Be Afraid', 'Isaiah 12', '[{"type": "cover", "img": "images/book/sep-20-0.jpg", "alt": "Cover illustration for “I Will Trust and Not Be Afraid”"}, {"type": "story", "img": "images/book/sep-20-1.jpg", "alt": "Illustration: After all his wonderful messages, Isaiah sang a happy song of trust.", "text": ["After all his wonderful messages, Isaiah sang a happy song of trust. It’s the song this whole week is named after!", "“Heavenly Father saves me!” Isaiah sang. “I will trust in Him, and I will not be afraid.”", "Isaiah knew that when Heavenly Father is with us, we don’t have to be scared. He is our strength when we feel weak, and He is our song when we feel sad."]}, {"type": "story", "img": "images/book/sep-20-2.jpg", "alt": "Illustration: “Heavenly Father is my strength and my song,” Isaiah sang joyfully.", "text": ["“Heavenly Father is my strength and my song,” Isaiah sang joyfully. Even in hard times, Isaiah chose to trust instead of being afraid.", "You can sing Isaiah’s song too! When something feels scary, you can remember: Heavenly Father is with me, so I will trust Him and not be afraid."]}, {"type": "moment", "img": "images/book/sep-20-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father instead of being afraid.", "text": ["Beau fits tonight because he trusts Heavenly Father instead of being afraid. In Beau’s world today: there was a big thunderstorm, and the loud booms made Beau’s heart jump. But he took a deep breath and remembered Isaiah’s song. “Heavenly Father is with me — I will trust and not be afraid,” he whispered, and he even hummed a little tune until the storm passed. Just like Isaiah sang about trusting and not fearing, Beau turned his scared feeling into a brave, trusting one."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-20-4.jpg", "alt": "Illustration: Let’s sing a brave, trusting song!", "text": ["Let’s sing a brave, trusting song! Stand up tall, put your hands on your heart, and say, “I will trust and not be afraid!” Now hum a happy, brave little tune. Can you show me your bravest, most trusting face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When something feels scary, you can sing Isaiah’s song — “Heavenly Father is with me, so I will trust and not be afraid!” What could you remember the next time you feel scared?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-20-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say he would NOT be?”", "“What did Isaiah say Heavenly Father was to him?”", "“What could you remember the next time you feel scared?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-20-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n7', 9, 'Week 3 · Night 7', 'Wells of Joy', 'Isaiah 12', '[{"type": "cover", "img": "images/book/sep-21-0.jpg", "alt": "Cover illustration for “Wells of Joy”"}, {"type": "story", "img": "images/book/sep-21-1.jpg", "alt": "Illustration: Isaiah’s happy song had one more joyful part.", "text": ["Isaiah’s happy song had one more joyful part. He sang about drawing up joy like cool water from a deep, wonderful well.", "“With joy you will draw water from the wells of Heavenly Father’s saving love!” Isaiah sang. Imagine a bucket coming up full — not of water, but of happiness!", "When we remember all the good things Heavenly Father does, our hearts fill up with joy, splashing over like a fresh, cool drink on a hot day."]}, {"type": "story", "img": "images/book/sep-21-2.jpg", "alt": "Illustration: And Isaiah didn’t want to keep the joy to himself.", "text": ["And Isaiah didn’t want to keep the joy to himself. “Tell everyone!” he sang. “Sing about the wonderful things Heavenly Father has done!”", "You can draw up joy too, just by remembering Heavenly Father’s love — and then share it with everyone, so the happiness spreads and spreads."]}, {"type": "moment", "img": "images/book/sep-21-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to find joy and share it with everyone.", "text": ["Scout fits tonight because Scout loves to find joy and share it with everyone. In Scout’s world today: Scout’s grandma got better after being sick, and Scout was so happy and grateful. Scout couldn’t hold the joy in — running to tell everyone, “Heavenly Father helped Grandma feel better!” Soon the whole family was smiling and thankful. Just like Isaiah sang about drawing up joy and telling everyone, Scout discovered that shared joy grows even bigger."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-21-4.jpg", "alt": "Illustration: Let’s draw up joy from the well!", "text": ["Let’s draw up joy from the well! Pretend to pull a rope hand over hand — up, up — then lift the happy bucket high and cheer, “Joy!” Now splash the joy to someone you love. Can you draw up your happiest bucket of joy?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can fill your heart with joy just by remembering Heavenly Father’s love — and then share it so the happiness grows! What good thing about Heavenly Father could you share with someone tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-21-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say we would draw up with joy?”", "“What did Isaiah want everyone to do with the good news?”", "“What good thing about Heavenly Father could you share with someone tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-21-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n1', 9, 'Week 4 · Night 1', 'He Wipes Away Every Tear', 'Isaiah 25', '[{"type": "cover", "img": "images/book/sep-22-0.jpg", "alt": "Cover illustration for “He Wipes Away Every Tear”"}, {"type": "story", "img": "images/book/sep-22-1.jpg", "alt": "Illustration: Isaiah shared a message so tender and kind that it feels like a warm hug from Heavenly Father.", "text": ["Isaiah shared a message so tender and kind that it feels like a warm hug from Heavenly Father.", "“Someday,” Isaiah said, “Heavenly Father will wipe away the tears from every face. There will be no more crying, and everyone will be happy!”", "Imagine Heavenly Father gently drying your tears with the softest, most loving touch, whispering, “It’s okay now, My child. Everything is going to be all right.”"]}, {"type": "story", "img": "images/book/sep-22-2.jpg", "alt": "Illustration: Heavenly Father sees every tear we cry.", "text": ["Heavenly Father sees every tear we cry. He cares about every sad feeling, and He loves to comfort us and turn our sadness into joy.", "Even when we feel sad today, we can remember Heavenly Father’s promise: He wipes away tears, and He fills our hearts with comfort and love."]}, {"type": "moment", "img": "images/book/sep-22-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to comfort and dry tears.", "text": ["Willow fits tonight because she loves to comfort and dry tears. In Willow’s world today: Willow’s little cousin was crying because she missed her mommy. Willow didn’t have a way to fix it, but she gently wiped her cousin’s tears and gave her a hug and sat close until she felt better. Just like Heavenly Father’s promise to wipe away every tear, Willow brought comfort with her gentle, loving care."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-22-4.jpg", "alt": "Illustration: Let’s feel Heavenly Father’s comfort!", "text": ["Let’s feel Heavenly Father’s comfort! Pretend to gently wipe a tear from your cheek, then give yourself a soft, warm hug. “It’s going to be okay.” Can you show me a sad face turning into a comforted, peaceful one?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father sees every tear and promises to wipe them all away — He loves to comfort you! Who can give you a comforting hug when you feel sad?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-22-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say Heavenly Father would wipe away?”", "“What does Heavenly Father do when we feel sad?”", "“Who can give you a comforting hug when you feel sad?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-22-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n2', 9, 'Week 4 · Night 2', 'Perfect Peace', 'Isaiah 26', '[{"type": "cover", "img": "images/book/sep-23-0.jpg", "alt": "Cover illustration for “Perfect Peace”"}, {"type": "story", "img": "images/book/sep-23-1.jpg", "alt": "Illustration: Isaiah shared a lovely secret about how to feel calm and peaceful inside, even when the world is busy.", "text": ["Isaiah shared a lovely secret about how to feel calm and peaceful inside, even when the world is busy.", "“Heavenly Father will keep you in perfect peace,” Isaiah said, “when you keep your mind on Him.”", "That means when we fill our thoughts with Heavenly Father — thinking about His love, remembering His stories — our hearts grow calm and quiet and peaceful."]}, {"type": "story", "img": "images/book/sep-23-2.jpg", "alt": "Illustration: It’s like when your mind is buzzing with worries, and then you think one gentle thought about Heavenly Father…", "text": ["It’s like when your mind is buzzing with worries, and then you think one gentle thought about Heavenly Father, and the buzzing settles into soft, warm peace.", "Heavenly Father wants to give you peace. When your thoughts turn to Him, He fills you up with a calm, safe, wonderful peace — the perfect kind."]}, {"type": "moment", "img": "images/book/sep-23-3.jpg", "alt": "Illustration: Wren fits tonight because she knows that thinking about Heavenly Father brings peace.", "text": ["Wren fits tonight because she knows that thinking about Heavenly Father brings peace. In Wren’s world today: Wren felt worried about her first day at a new class — her thoughts were spinning fast. So she closed her eyes and thought about how Heavenly Father loved her and was with her. Slowly, her spinning thoughts grew calm and peaceful. Just like Isaiah said keeping our minds on Heavenly Father brings perfect peace, Wren found calm by thinking of Him."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-23-4.jpg", "alt": "Illustration: Let’s find perfect peace!", "text": ["Let’s find perfect peace! Put your hands on the sides of your head, then slowly move them down as you take a deep breath, thinking one calm thought about Heavenly Father. Can you show me your peaceful, settled face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When your thoughts feel busy or worried, you can think about Heavenly Father — and He fills you with perfect peace! What happy thought about Heavenly Father could you think when you feel worried?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-23-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How do we get Heavenly Father’s perfect peace?”", "“What happens when we keep our minds on Heavenly Father?”", "“What happy thought about Heavenly Father could you think when you feel worried?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-23-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n3', 9, 'Week 4 · Night 3', 'A Sure, Strong Rock', 'Isaiah 26', '[{"type": "cover", "img": "images/book/sep-24-0.jpg", "alt": "Cover illustration for “A Sure, Strong Rock”"}, {"type": "story", "img": "images/book/sep-24-1.jpg", "alt": "Illustration: Isaiah taught that Heavenly Father is like the strongest, most reliable rock you could ever build on.", "text": ["Isaiah taught that Heavenly Father is like the strongest, most reliable rock you could ever build on.", "“Trust in Heavenly Father forever,” Isaiah said, “for He is like a Rock that lasts always and always.”", "He also said Heavenly Father is like a precious, sure cornerstone — the special, strong stone builders use to hold a whole house together, so it never falls."]}, {"type": "story", "img": "images/book/sep-24-2.jpg", "alt": "Illustration: When we build our lives on Heavenly Father, we’re standing on something that will never wobble, crack, or crum…", "text": ["When we build our lives on Heavenly Father, we’re standing on something that will never wobble, crack, or crumble. He is steady and strong forever.", "No matter what happens around us, Heavenly Father holds us firm. When we trust in Him, we are safe and steady, standing on the strongest Rock of all."]}, {"type": "moment", "img": "images/book/sep-24-3.jpg", "alt": "Illustration: Beau fits tonight because he stands strong on Heavenly Father.", "text": ["Beau fits tonight because he stands strong on Heavenly Father. In Beau’s world today: Beau was learning to balance on the low wall at the park, and his legs felt wobbly and unsure. He remembered that Heavenly Father was his strong Rock, holding him steady. He took a brave breath, steadied himself, and walked the whole way! Just like Isaiah said to trust Heavenly Father, the Rock that lasts forever, Beau found his steady footing by leaning on Him."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-24-4.jpg", "alt": "Illustration: Let’s stand on the strong Rock!", "text": ["Let’s stand on the strong Rock! Plant your feet wide, make your body big and firm, and don’t wobble — steady as a rock! Now say, “Heavenly Father is my strong Rock!” Can you stand as steady and sure as stone?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is your sure, strong Rock — when you trust in Him, you can stand steady and safe forever! When could you lean on Heavenly Father to feel steady?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-24-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What strong, steady thing did Isaiah say Heavenly Father is like?”", "“What happens when we build our lives on Heavenly Father?”", "“When could you lean on Heavenly Father to feel steady?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-24-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n4', 9, 'Week 4 · Night 4', 'A Marvellous Work and a Wonder', 'Isaiah 29', '[{"type": "cover", "img": "images/book/sep-25-0.jpg", "alt": "Cover illustration for “A Marvellous Work and a Wonder”"}, {"type": "story", "img": "images/book/sep-25-1.jpg", "alt": "Illustration: This week’s book is named after something Isaiah said Heavenly Father would do: “a marvellous work and a wonde…", "text": ["This week’s book is named after something Isaiah said Heavenly Father would do: “a marvellous work and a wonder!”", "That means Heavenly Father does amazing, surprising, wonderful things — things so good and clever that they make us say, “Wow!”", "Isaiah promised that Heavenly Father would do a wonder that would help all His children — teaching and blessing even those who thought they couldn’t learn."]}, {"type": "story", "img": "images/book/sep-25-2.jpg", "alt": "Illustration: Heavenly Father is full of surprises!", "text": ["Heavenly Father is full of surprises! He can make wonderful things happen in ways we never even imagined. His works are truly marvelous.", "When you see something amazing — a rainbow, a new baby, a kind miracle — you can remember: Heavenly Father is still doing marvelous works and wonders, today and always."]}, {"type": "moment", "img": "images/book/sep-25-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to discover Heavenly Father’s marvelous wonders.", "text": ["Scout fits tonight because Scout loves to discover Heavenly Father’s marvelous wonders. In Scout’s world today: after a rainstorm, Scout spotted a huge, bright rainbow arching across the whole sky. “How does Heavenly Father DO that?” Scout gasped, staring in wonder. It felt like a marvelous surprise made just for that moment. Just like Isaiah said Heavenly Father does a marvellous work and a wonder, Scout discovered that His amazing works are everywhere."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-25-4.jpg", "alt": "Illustration: Let’s be amazed at Heavenly Father’s wonders!", "text": ["Let’s be amazed at Heavenly Father’s wonders! Open your eyes and mouth w-i-d-e in a big “WOW!” and throw your hands up in surprise. Heavenly Father does marvelous things! Can you show me your most amazed, wonder-filled face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father does marvelous works and wonders — amazing, surprising, wonderful things — today and always! What marvelous thing that Heavenly Father made amazes you most?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-25-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say Heavenly Father would do?”", "“What do marvelous works make us want to say?”", "“What marvelous thing that Heavenly Father made amazes you most?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-24-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n5', 9, 'Week 4 · Night 5', 'This Is the Way', 'Isaiah 30', '[{"type": "cover", "img": "images/book/sep-26-0.jpg", "alt": "Cover illustration for “This Is the Way”"}, {"type": "story", "img": "images/book/sep-26-1.jpg", "alt": "Illustration: Isaiah shared a comforting message about how Heavenly Father helps us know which way to go.", "text": ["Isaiah shared a comforting message about how Heavenly Father helps us know which way to go.", "“When you’re not sure which way to turn,” Isaiah said, “you will hear a gentle voice behind you saying, ‘This is the way — walk in it.’”", "Heavenly Father helps guide us, like a kind whisper in our hearts showing us the right path — the good and safe way to go.", "Isaiah also said that being quiet and calm helps us hear Him. “In quietness and trust is your strength,” he taught. When we get still, we can feel Heavenly Father’s gentle guidance."]}, {"type": "story", "img": "images/book/sep-26-2.jpg", "alt": "Illustration: Whenever you don’t know what’s right, you can get quiet, listen with your heart, and trust Heavenly Father to…", "text": ["Whenever you don’t know what’s right, you can get quiet, listen with your heart, and trust Heavenly Father to whisper, “This is the way.” He always helps you find the good path."]}, {"type": "moment", "img": "images/book/sep-26-3.jpg", "alt": "Illustration: Wren fits tonight because she gets quiet and listens with her heart.", "text": ["Wren fits tonight because she gets quiet and listens with her heart. In Wren’s world today: Wren wasn’t sure whether to share her new crayons or keep them all to herself. Instead of rushing, she got quiet and thought about what was kind. In the calm, she felt a gentle nudge in her heart: sharing is the good way. She shared, and it felt right. Just like Isaiah said we hear “this is the way” when we’re quiet and trusting, Wren listened and found the good path."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-26-4.jpg", "alt": "Illustration: Let’s listen for the way!", "text": ["Let’s listen for the way! Cup your hand to your ear and get very quiet… then point ahead and whisper, “This is the way!” Now take a peaceful step forward. Can you show me your best quiet- listening ears?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you’re not sure what’s right, you can get quiet and listen — Heavenly Father will gently guide you, whispering, “This is the way!” When could you get quiet and listen for the good way?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-26-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What gentle words does Heavenly Father help us hear?”", "“What helps us hear Heavenly Father’s guidance?”", "“When could you get quiet and listen for the good way?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-26-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n6', 9, 'Week 4 · Night 6', 'The Desert Blooms', 'Isaiah 35', '[{"type": "cover", "img": "images/book/sep-27-0.jpg", "alt": "Cover illustration for “The Desert Blooms”"}, {"type": "story", "img": "images/book/sep-27-1.jpg", "alt": "Illustration: Isaiah painted the most beautiful picture of hope.", "text": ["Isaiah painted the most beautiful picture of hope. He told about a dry, empty desert — and then something wonderful happened!", "“The desert will be glad,” Isaiah said, “and the dry, thirsty ground will burst into bloom with flowers! It will blossom like a beautiful rose.”", "Imagine a bare, brown place suddenly filling up with soft green grass, splashing streams, and bright, happy flowers everywhere. That’s what Heavenly Father can do!"]}, {"type": "story", "img": "images/book/sep-27-2.jpg", "alt": "Illustration: Heavenly Father can bring beautiful life to even the driest, saddest places.", "text": ["Heavenly Father can bring beautiful life to even the driest, saddest places. He turns empty into full, and sad into glad, and brown into bloom.", "When your heart feels dry or sad, remember: Heavenly Father can make good things bloom again. With Him, there is always hope for something beautiful."]}, {"type": "moment", "img": "images/book/sep-27-3.jpg", "alt": "Illustration: Willow fits tonight because she believes good things can bloom again.", "text": ["Willow fits tonight because she believes good things can bloom again. In Willow’s world today: Willow’s favorite little plant looked droopy and brown, and she felt sad. But Mom showed her how to water it and set it in the sun. Day by day, it grew green and even sprouted a tiny flower! Willow clapped with joy. Just like Isaiah’s desert that blossomed like a rose, Willow learned that with gentle care and hope, beautiful things can bloom."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-27-4.jpg", "alt": "Illustration: Let’s watch the desert bloom!", "text": ["Let’s watch the desert bloom! Crouch down small like dry, cracked ground, then slowly grow up and open your arms wide like a flower bursting into bloom. Can you show me the empty desert blossoming into a beautiful garden?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father can make good things bloom, even in the driest, saddest places — so there’s always hope for something beautiful! What is something you’re hopeful will get better and bloom?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-27-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say the dry desert would do?”", "“What can Heavenly Father do to dry, sad places?”", "“What is something you’re hopeful will get better and bloom?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-27-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n7', 9, 'Week 4 · Night 7', 'Be Strong, Don’t Be Afraid', 'Isaiah 35', '[{"type": "cover", "img": "images/book/sep-28-0.jpg", "alt": "Cover illustration for “Be Strong, Don’t Be Afraid”"}, {"type": "story", "img": "images/book/sep-28-1.jpg", "alt": "Illustration: Isaiah’s beautiful message ended with words of courage and joy — a wonderful way to finish the whole month!", "text": ["Isaiah’s beautiful message ended with words of courage and joy — a wonderful way to finish the whole month!", "“Be strong, and don’t be afraid,” Isaiah said. “Heavenly Father is coming to help you and save you!”", "In Isaiah’s happy picture, wonderful things happen: streams splash through the desert, and everyone who was sad leaps and sings for joy. “Sorrow and sighing fly away!”"]}, {"type": "story", "img": "images/book/sep-28-2.jpg", "alt": "Illustration: Isaiah even told of a special, safe road — a happy path that leads home to Heavenly Father, where His people w…", "text": ["Isaiah even told of a special, safe road — a happy path that leads home to Heavenly Father, where His people walk and sing with joy forever.", "So be strong and brave, little one! Heavenly Father is always helping you and leading you home. And on the way, He fills our hearts with singing, and turns all our sorrow into joy."]}, {"type": "moment", "img": "images/book/sep-28-3.jpg", "alt": "Illustration: Beau fits tonight because his courage carries him all the way to joy.", "text": ["Beau fits tonight because his courage carries him all the way to joy. In Beau’s world today: Beau felt nervous about riding his bike without training wheels — it seemed so hard and a little scary. But he remembered to be strong and not afraid, took a deep breath, and pushed off. Wobble, wobble — then he was riding! He leaped off, cheering with pure joy. Just like Isaiah said, “Be strong, don’t be afraid,” Beau’s brave heart turned into a happy, joyful one."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-28-4.jpg", "alt": "Illustration: Let’s be strong and joyful!", "text": ["Let’s be strong and joyful! Flex your muscles strong — “I am brave!” — then leap up high and cheer, “Joy!” Sorrow flies away! Can you show me strong and brave, then leaping with joy?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Be strong and don’t be afraid — Heavenly Father is always helping you and leading you home, and He turns sorrow into joy! What is something brave and strong Heavenly Father can help you do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-28-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say to be, instead of afraid?”", "“What happens to sorrow and sighing in Isaiah’s happy message?”", "“What is something brave and strong Heavenly Father can help you do?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-28-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

-- ---------------------------------------------------------------------
-- WHICH STORIES ARE FREE
-- The same three as meta.freeStoryIds in data/virtue-library.js. Keep the
-- two lists the same, or a story is free in one place and not the other.
-- ---------------------------------------------------------------------
update public.book_nights set is_free = (id in ('b6-w3-n1', 'b7-w1-n7', 'b6-w3-n4'));

-- ---------------------------------------------------------------------
-- DID IT WORK? Last statement, so this is what the Results panel shows.
-- ---------------------------------------------------------------------
select book, count(*) as nights,
       count(*) filter (where is_free) as "free ones"
  from public.book_nights group by book order by book;
